uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float twinkle : 0.0 .. 1.0 = 0.3;
uniform float zoom : 0.5 .. 3.0 = 1.0;
state fixed ph;
void update() {
  ph = fract(ph + fixed(dt * speed));
}
vec3 shade(Led led) {
  fixed ang = atan2(fixed(led.pos.z), fixed(led.pos.x)) + fixed(0.5);
  fixed r = sqrt(fixed(led.pos.x) * fixed(led.pos.x) + fixed(led.pos.z) * fixed(led.pos.z));
  fixed tw = fract(r * fixed(20.0) + ph * fixed(3.0));
  fixed t = smoothstep(fixed(0.5), fixed(0.0), tw);
  fixed3 col = hsv2rgb(fixed(led.uv.x), fixed(1.0), t * fixed(1.0));
  return vec3(col.r, col.g, col.b);
}

